extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var q := Question.new("Qual è la capitale?", ["Roma", "Parigi"], 0)
	if not check("create", q != null, "L'istanza di Question creata con new() non deve essere null"):
		return
	check("text", q.text == "Qual è la capitale?", "La proprietà text deve contenere il testo passato a _init")
	check("options", q.options.size() == 2 and q.options[0] == "Roma", "La proprietà options deve contenere le opzioni passate")
	check("correct_index", q.correct_index == 0, "La proprietà correct_index deve valere 0")
	check("is_correct_true", q.is_correct(0), "is_correct(0) deve restituire true quando l'indice corretto è 0")
	check("is_correct_false", not q.is_correct(1), "is_correct(1) deve restituire false quando l'indice corretto è 0")

	var raw := {
		"question": "Quanto fa 2+2?",
		"options": ["3", "4", "5"],
		"correct": 1
	}
	var from_d := Question.from_dict(raw)
	if check("from_dict_not_null", from_d != null, "Question.from_dict deve restituire un'istanza valida"):
		check("from_dict_text", from_d.text == "Quanto fa 2+2?", "from_dict deve estrarre correttamente la domanda")
		check("from_dict_correct", from_d.correct_index == 1, "from_dict deve estrarre l'indice corretto")
		check("from_dict_check", from_d.is_correct(1), "La domanda creata da from_dict deve riconoscere la risposta esatta")

